        this.id = id;
    }
}
public class Main {
    static Item create(boolean flag) {
        var a = new Item();
        if (flag) return a;
        return new Item(50);
    }
    public static void main(String[] args) {
        Item x = create(false);
        System.out.println(Item.count + ":" + x.id);
    }
}

interface Shape {
}
record Circle(int r) implements Shape {
}
record Rect(int w, int h) implements Shape {
}
public class Main {
    static int areaCode(Shape s) {
        if (s instanceof Circle c && c.r() > 2) {
            return c.r() * 10;
        }
        if (s instanceof Rect r) {
            return r.w() + r.h();
        }
        return -1;
    }
    public static void main(String[] args) {
        Shape s = new Circle(3);
        System.out.println(areaCode(s));
    }
}

